def has_surrogate(s):
    return any(0xDC80 <= ord(c) <= 0xDCFF for c in s)

# ---------- Rust-like Path helpers (Unix) ----------

def is_abs_path(p):
    return p.startswith("/")

def rjoin(base, other):
    if is_abs_path(other):
        return other
    if base == "":
        return other
    if base.endswith("/"):
        return base + other
    return base + "/" + other

def path_components(p):
    if p == "":
        return []
    absolute = p.startswith("/")
    comps = []
    if absolute:
        comps.append("/")
    for seg in p.split("/"):
        if seg == "":
            continue
        if seg == ".":
            if not absolute and len(comps) == 0:
                comps.append(".")
            continue
        comps.append(seg)
    return comps

def components_to_path(comps):
    if not comps:
        return ""
    if comps[0] == "/":
        if len(comps) == 1:
            return "/"
        return "/" + "/".join(comps[1:])
    return "/".join(comps)

def path_file_name(p):
    comps = path_components(p)
    if not comps:
        return None
    last = comps[-1]
    if last in ("/", "..", "."):
