        return None
    if len(comps) == 1:
        # a single relative component (or "." / "..") has parent ""
        return ""
    return components_to_path(comps[:-1])

def split_stem_ext(filename):
    # Rust file_stem/extension on a file name.
    if filename.startswith(".") and "." not in filename[1:]:
        return filename, None
    idx = filename.rfind(".")
    if idx == -1:
        return filename, None
    return filename[:idx], filename[idx+1:]

def path_file_stem(p):
    fn = path_file_name(p)
    if fn is None:
        return None
    return split_stem_ext(fn)[0]

def entry_stem_ext(name):
    return split_stem_ext(name)

def with_extension(path, ext):
    fn = path_file_name(path)
    if fn is None:
        return path
    stem, _old = split_stem_ext(fn)
    new_name = stem + ("." + ext if ext != "" else "")
    parent = path_parent(path)
    if parent is None:
        return new_name
    if parent == "":
        return new_name
    return rjoin(parent, new_name)

def starts_with_path(path, base):
    pc = path_components(path)
    bc = path_components(base)
    return len(bc) <= len(pc) and pc[:len(bc)] == bc

def strip_prefix_path(path, base):
    pc = path_components(path)
    bc = path_components(base)
    if pc[:len(bc)] != bc:
        return None
    rest = pc[len(bc):]
    return "/".join(rest)

def lexists(p):
    return os.path.lexists(p)

def path_exists(p):
