def _fallback_parse_toml(text):
    # A small TOML parser sufficient for the documents this program
    # writes and for typical hand edits of them.  It is only used when
    # neither tomllib (3.11+) nor tomli is available.
    pos = 0
    n = len(text)
    root = {}
    current = root

    def err():
