                else:
                    out.append(c); pos += 1
        else:
            pos += 1
            out = []
            while True:
                if pos >= n or text[pos] in "\r\n":
                    err()
                c = text[pos]; pos += 1
                if c == '"':
                    return ''.join(out)
                if c == "\\":
                    if pos >= n:
                        err()
                    e = text[pos]; pos += 1
                    mp = {"b":"\b","t":"\t","n":"\n","f":"\f","r":"\r",'"':'"', "\\":"\\"}
                    if e in mp:
                        out.append(mp[e])
                    elif e == "u":
                        out.append(chr(int(text[pos:pos+4], 16))); pos += 4
                    elif e == "U":
