            out.append('"' if multiline else '\\"')
        elif ch == "\\":
            out.append("\\\\")
        elif ch == "\b":
            out.append("\\b")
        elif ch == "\t":
            if multiline:
                out.append("\t")
            else:
                out.append("\\t")
        elif ch == "\n":
            out.append("\n" if multiline else "\\n")
        elif ch == "\f":
            out.append("\\f")
        elif ch == "\r":
            out.append("\\r")
        elif o < 0x20 or o == 0x7f:
            out.append(f"\\u{o:04X}")
        else:
            out.append(ch)
    return ''.join(out)

def toml_string(s):
