    has_nl = "\n" in s
    can_literal = ("'" not in s) and (not has_nl) and all(raw_ok(c, False) for c in s)
    if can_literal:
        return "'" + s + "'"
    can_ml_literal = ("''" + "'" not in s) and (not s.endswith("'")) and all(raw_ok(c, True) for c in s)
