def load_or_create(path, default_factory, serializer, validator):
    # Rust try_exists-like behaviour: a stat that fails for a reason
    # other than "not found" is treated as "exists" and the following
    # read then panics with "couldn't load file".
    try:
        os.stat(path)
        exists = True
    except FileNotFoundError:
        exists = False
    except OSError:
        exists = True
    if not exists:
        parent = path_parent(path)
        _create_dir_all_p(parent)
        obj = default_factory()
        try:
            with open(path, "w", encoding="utf-8", newline="\n") as f:
                f.write(serializer(obj))
        except OSError as e:
            panic_result_unwrap_io("src/traits.rs:49:76", e)
