    try:
        sys.stdout.buffer.flush()
    except Exception:
        pass
    try:
        subprocess.run([editor, path])
    except OSError as e:
        if e.errno == errno.ENOENT:
            raise JotError("editor not found")
        err_undefined(e)

# Resolving a user supplied path against the current vault folder,
# used by chdir and by move (for notes/folders).
def resolve_in_vault(state, v, user_path):
    root = state.vault_root(v, location_first=True)
    cur_raw = rjoin(root, v["folder"])
    try:
        cur_canonical = canonicalize(cur_raw)
    except OSError:
        raise JotError("couldn't find the path specified")
    candidate_raw = rjoin(cur_raw, user_path)
    try:
        candidate = canonicalize(candidate_raw)
    except OSError:
        raise JotError("couldn't find the path specified")
    if path_components(candidate) == path_components(cur_canonical):
        raise JotError("new location is same as old location")
    if not starts_with_path(candidate, root):
        raise JotError("path crosses the bounds of vault")
    return candidate

# ---------- Move machinery (copy + delete, like fs_extra) ----------

def _copy_file(src, dst):
    with open(src, "rb") as fsrc:
        with open(dst, "wb") as fdst:
            shutil.copyfileobj(fsrc, fdst, length=1024 * 64)
    # std::fs::copy copies permission bits.
    try:
        shutil.copymode(src, dst)
    except Exception:
        pass

def _copy_dir(src, dst):
    # First gather the tree (following symlinks for classification),
    # so a failure while walking leaves no destination behind.
    dirs = []
    files = []

    def walk(rel):
        here = rjoin(src, rel) if rel else src
        for e in os.scandir(here):
            rel_e = f"{rel}/{e.name}" if rel else e.name
            st = os.stat(e.path)
            if stat.S_ISDIR(st.st_mode):
                dirs.append(rel_e)
                walk(rel_e)
            else:
                files.append(rel_e)

    walk("")
    os.mkdir(dst)
    for rel in dirs:
        os.mkdir(rjoin(dst, rel))
    for rel in files:
        _copy_file(rjoin(src, rel), rjoin(dst, rel))

def move_item(canonical_type, name, source_dir, dest_dir):
    if path_components(source_dir) == path_components(dest_dir):
        raise JotError("new location is same as old location")
    if invalid_name(name):
        raise JotError("invalid name")
    src = item_path(source_dir, name, canonical_type)
    dst = item_path(dest_dir, name, canonical_type)
    if path_exists(dst):
        raise JotError(f"a {canonical_type} named {name} already exists in this location")
    try:
        src_stat = os.stat(src)
    except OSError as e:
        err_move_io(e)
    if lexists(dest_dir) and not os.path.isdir(dest_dir):
        raise JotError("io error")
    try:
        if stat.S_ISDIR(src_stat.st_mode):
            _copy_dir(src, dst)
            remove_dir_all(src)
        else:
            _copy_file(src, dst)
            os.unlink(src)
    except JotError:
        raise
    except OSError as e:
        err_move_io(e)

