        if state.vaults.get("current") == name:
            state.vaults["current"] = new_name
        state.save_vaults()
        out_write(f"vault {blue(name)} renamed to {blue(new_name)}\n")
        return
    v = state.require_vault()
    cur = state.current_folder_path(v, location_first=False)
