class _Peekable:
    def __init__(self, it):
        self._it = it
        self._buf = []
        self._exhausted = False

    def _fill(self):
        if self._buf or self._exhausted:
            return
        try:
            self._buf.append(next(self._it))
        except StopIteration:
            self._exhausted = True

    def has_next(self):
        self._fill()
        return bool(self._buf)

    def next(self):
        self._fill()
        if self._buf:
            return self._buf.pop(0)
        return None

