HANDLERS = {
    "vault": cmd_vault,
    "note": cmd_note,
    "folder": cmd_folder,
    "enter": cmd_enter,
    "open": cmd_open,
    "opdir": cmd_opdir,
    "chdir": cmd_chdir,
    "list": cmd_list,
    "remove": cmd_remove,
    "rename": cmd_rename,
    "move": cmd_move,
    "vmove": cmd_vmove,
    "config": cmd_config,
}

def write_panic(p):
    try:
        sys.stdout.buffer.flush()
    except Exception:
        pass
    bt = os.environ.get("RUST_BACKTRACE")
    if bt is None:
        bt = os.environ.get("RUST_LIB_BACKTRACE")
    msg = f"\nthread 'main' ({os.getpid()}) panicked at {p.location}:\n{p.message}\n"
    if bt and bt != "0":
        if bt == "full":
            msg += "stack backtrace:\n"
        else:
            msg += "stack backtrace:\nnote: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n"
    else:
        msg += "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    err_write(msg)

def main():
    argv0 = sys.argv[0] if sys.argv else "jt"
    bin_name = argv0.replace("\\", "/").rsplit("/", 1)[-1] or argv0
    try:
        command, args = parse_root(sys.argv[1:], bin_name)
        state = State()
        HANDLERS[command](state, args)
        return 0
    except CliExit as e:
        return getattr(e, "code", 2)
    except RustPanic as p:
        write_panic(p)
        return 101
    except JotError as e:
        out_write(f"{RED}error{RESET}: {e}\n")
        return 0
    except BrokenPipeError:
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        except Exception:
            pass
        return 101

if __name__ == "__main__":
    sys.exit(main())
