newparse='''def parse_subcommand(spec, args, bin_name):
    values = {}
    used = set()
    positional_index = 0
    after_dd = False
    flag_l_count = 0
    help_requested = False

    def assign(token):
        nonlocal positional_index
        if positional_index >= len(spec.positionals):
            err_write(f"error: Found argument '{lossy(token)}' which wasn't expected, or isn't valid in this context\\n\\n{usage_labelled(spec.raw_usage(bin_name))}")
            raise CliExit()
        arg = spec.positionals[positional_index]
        positional_index += 1
        used.add(arg.name)
        values[arg.name] = token

    i = 0
    while i < len(args) and not help_requested:
        token = args[i]
        i += 1
        if not after_dd and token == "--":
            after_dd = True
            continue
        if not after_dd and token.startswith("-") and token != "-":
            if token.startswith("--"):
                eq = token.find("=")
                long_name = token[2:eq] if eq != -1 else token[2:]
                display = "--" + long_name
                if long_name == "help":
                    if eq != -1:
                        err_too_many_help_values(spec, bin_name, token[eq+1:])
                    help_requested = True
                    break
                else:
                    cand = did_you_mean(lossy(long_name), ["help"])
                    suggestion = "--help" if cand else None
                    unknown_flag(spec, bin_name, display, used, suggestion, is_long=True)
            else:
                for ch in token[1:]:
                    if ch == "h":
                        help_requested = True
                        break
                    elif spec.has_l and ch == "l":
                        flag_l_count += 1
                        values["-l"] = True
                    else:
                        unknown_flag(spec, bin_name, "-" + ch, used, None, is_long=False)
            continue
        assign(token)

    # Value validation happens after lexical parsing (and after a
    # help flag terminates it), before help is displayed and before
    # required-argument / duplicate-flag checks.
    for pos in spec.positionals:
        if pos.name not in values:
            continue
        token = values[pos.name]
        if token == "" and not pos.allow_empty:
            err_write(f"error: The argument '<{pos.name}>' requires a value but none was supplied\\n\\nFor more information try --help\\n")
            raise CliExit()
        if pos.possible is not None:
            if token not in pos.possible:
                err_invalid_value(bin_name, pos, token)
        elif not pos.is_path and is_invalid_utf8(token):
            err_invalid_utf8(spec, bin_name)

    if help_requested:
        display_spec_help(spec, bin_name)

    if flag_l_count > 1:
        err_write(f"error: The argument '-l' was provided more than once, but cannot be used multiple times\\n\\n{usage_labelled(spec.raw_usage(bin_name))}")
        raise CliExit()

    missing = []
    if spec.canonical == "vault":
        if "vault name" in values and "vault location" not in values:
            missing.append("vault location")
    elif spec.canonical == "config":
        missing = []
    else:
        for pos in spec.positionals:
            if pos.required and pos.name not in values:
                missing.append(pos.name)
    if missing:
        err_missing(spec, bin_name, missing)
    return values

'''
